"""generates the 'iw.db' file to be consumed by BIND"""

import glob
import os
import pickle

from dumbschema import dumb_parse_object

serial = 1
old_domains = set()
old_nameservers = set()

if os.path.exists(".serial"):
    with open(".serial", "rb") as file:
        serial = pickle.load(file)
    os.unlink(".serial")

if os.path.exists(".zone-data"):
    with open(".zone-data", "rb") as file:
        serial, old_domains, old_nameservers = pickle.load(file)


def HEADER(origin):
    return f"""; This file was autogenerated by utils/generate_zone.py
; Do not edit! It will be regenerated.
$ORIGIN {origin}
$TTL 1h
@ IN SOA v.root-servers.iw. contact.itsvic.dev. {serial} 1h 15m 4d 30m
"""


domains = set()
nameservers = set()

for file in glob.iglob("data/dns/*"):
    with open(file) as f:
        obj = dumb_parse_object(f.read())
    nservers = obj["nserver"]
    domain = obj["domain"]
    if type(nservers) is not list:  # single nserver defined
        nservers = [nservers]

    for nserver in nservers:
        ns, a = [i.strip() for i in nserver.split(" ", 1)]  # pyright: ignore[reportAttributeAccessIssue]
        domains.add((domain, ns))
        nameservers.add((ns, a))

if domains == old_domains and nameservers == old_nameservers:
    print("Domains are identical, skipping update")
    exit()

with open("iw.db", "w+") as file:
    file.write(HEADER("iw.") + "\n")
    for domain, ns in sorted(list(domains)):
        file.write(f"{domain}. IN NS {ns}.\n")
    file.write("\n")
    for ns, a in sorted(list(nameservers)):
        file.write(f"{ns}. IN A {a}\n")

with open("root.db", "w+") as file:
    file.write(HEADER(".") + "\n")
    iw_ns = [ns for domain, ns in domains if domain == "iw"]
    for domain, ns in sorted([d for d in domains if d[0] == "iw"]):
        file.write(f". IN NS {ns}.\n")
        file.write(f"{domain}. IN NS {ns}.\n")
    for ns, a in sorted(list(nameservers)):
        if ns not in iw_ns:
            continue
        file.write(f"{ns}. IN A {a}\n")
    file.write("\n")
    with open("utils/root.db") as icann_root_file:
        file.write(icann_root_file.read())

with open(".zone-data", "wb+") as file:
    pickle.dump((serial + 1, domains, nameservers), file)
